CREATE TABLE public.note_presets (id uuid DEFAULT gen_random_uuid() NOT NULL, label text NOT NULL, sort_order smallint NOT NULL, is_active boolean DEFAULT true NOT NULL);
ALTER TABLE public.note_presets ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.note_presets ADD CONSTRAINT note_presets_label_key UNIQUE (label);
ALTER TABLE public.note_presets ADD CONSTRAINT note_presets_pkey PRIMARY KEY (id);
ALTER TABLE public.note_presets ADD CONSTRAINT note_presets_sort_order_key UNIQUE (sort_order);
GRANT MAINTAIN, REFERENCES, TRIGGER, TRUNCATE ON public.note_presets TO anon;
GRANT MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE ON public.note_presets TO authenticated;
GRANT ALL ON public.note_presets TO service_role;
CREATE POLICY "Note presets are viewable by all authenticated users" ON public.note_presets FOR SELECT TO authenticated USING (true);
CREATE TABLE public.notes (id uuid DEFAULT gen_random_uuid() NOT NULL, reading_id uuid NOT NULL, user_id uuid NOT NULL, preset_id uuid, body text, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
ALTER TABLE public.notes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.notes ADD CONSTRAINT notes_has_content CHECK (preset_id IS NOT NULL OR body IS NOT NULL);
ALTER TABLE public.notes ADD CONSTRAINT notes_pkey PRIMARY KEY (id);
ALTER TABLE public.notes ADD CONSTRAINT notes_preset_id_fkey FOREIGN KEY (preset_id) REFERENCES public.note_presets(id) ON DELETE SET NULL;
ALTER TABLE public.notes ADD CONSTRAINT notes_reading_id_fkey FOREIGN KEY (reading_id) REFERENCES public.readings(id) ON DELETE CASCADE;
ALTER TABLE public.notes ADD CONSTRAINT notes_reading_id_key UNIQUE (reading_id);
ALTER TABLE public.notes ADD CONSTRAINT notes_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;
GRANT MAINTAIN, REFERENCES, TRIGGER, TRUNCATE ON public.notes TO anon;
GRANT ALL ON public.notes TO authenticated;
GRANT ALL ON public.notes TO service_role;
CREATE INDEX notes_reading_id_idx ON public.notes (reading_id);
CREATE INDEX notes_user_id_idx ON public.notes (user_id);
CREATE TRIGGER notes_set_updated_at BEFORE UPDATE ON public.notes FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE POLICY "Notes are deletable by owner" ON public.notes FOR DELETE TO authenticated USING ((( SELECT auth.uid() AS uid) = user_id));
CREATE POLICY "Notes are insertable by owner" ON public.notes FOR INSERT TO authenticated WITH CHECK ((( SELECT auth.uid() AS uid) = user_id));
CREATE POLICY "Notes are updatable by owner" ON public.notes FOR UPDATE TO authenticated USING ((( SELECT auth.uid() AS uid) = user_id)) WITH CHECK ((( SELECT auth.uid() AS uid) = user_id));
CREATE POLICY "Notes are viewable by owner" ON public.notes FOR SELECT TO authenticated USING ((( SELECT auth.uid() AS uid) = user_id));
